<p class="muted"><a href="/products">Sản phẩm</a> / <?= e($product['category_name']) ?></p><div class="panel detail-grid"><section><img id="product-main-image" class="detail-image" src="<?= e($product['images'][0]['path']??'/assets/img/device-'.$product['category_id'].'.svg') ?>" alt="<?= e($product['name']) ?>"><div class="d-flex gap-2"><?php foreach($product['images'] as $image):?><button class="btn p-0" data-image="<?= e($image['path']) ?>" aria-label="Xem ảnh sản phẩm"><img class="thumb" src="<?= e($image['path']) ?>" alt="Ảnh <?= e($product['name']) ?>"></button><?php endforeach?></div></section><section><span class="badge-soft"><?= e($product['brand_name']) ?></span><h1 class="page-title mt-3"><?= e($product['name']) ?></h1><p class="muted">Mã sản phẩm: <?= e($product['sku']) ?></p><div class="detail-price"><?= money($product['price']) ?></div><p><?= $product['stock']>0?'Còn '.$product['stock'].' sản phẩm':'Hết hàng' ?></p><p class="muted lh-lg"><?= e($product['description']) ?></p><form action="/cart/update" method="post" data-ajax class="d-flex gap-2 my-4"><?= App\Core\Csrf::field() ?><input name="product_id" type="hidden" value="<?= $product['id'] ?>"><input class="form-control quantity" name="quantity" type="number" min="1" max="<?= $product['stock'] ?>" value="1" aria-label="Số lượng"><button class="btn btn-primary" id="detail-add-cart" type="submit" <?= $product['stock']<1?'disabled':'' ?>>Thêm vào giỏ hàng</button></form><form action="/compare/update" method="post" data-ajax><?= App\Core\Csrf::field() ?><input name="product_id" type="hidden" value="<?= $product['id'] ?>"><button id="detail-compare" type="submit" class="btn btn-outline-primary">⇄ Thêm vào so sánh</button></form></section></div><section class="panel"><h2>Thông số kỹ thuật</h2><table class="table"><tbody><?php foreach($product['specs'] as $s):?><tr><th><?= e($s['spec_key']) ?></th><td><?= e($s['spec_value']) ?></td></tr><?php endforeach?></tbody></table></section>
